/**
 * FreeLang Nexus - WebAssembly 런타임 실행기
 *
 * Phase N.4.2 — WAT → .wasm 바이너리 변환 + Node.js 실행
 *
 * 역할:
 *  1. FreeLang 소스 → NexusWasmCodegen으로 WAT 생성
 *  2. wabt npm 패키지로 WAT → .wasm 바이너리 변환
 *  3. WebAssembly.instantiate 로 Node.js에서 실행
 *  4. export된 함수 호출 및 결과 반환
 *
 * wabt 미설치 환경에서는 자동으로 unavailable 플래그를 세움
 */

import { NexusLexer } from '../lexer/nexus-lexer';
import { NexusParser } from '../parser/nexus-parser';
import { NexusWasmCodegen } from '../codegen/nexus-wasm-codegen';

// ─── wabt 동적 로드 (미설치 환경 안전 처리) ───────────────────────────────────

let wabtLoader: (() => Promise<any>) | null = null;

try {
  // require 시도: wabt 패키지가 있으면 로더 등록
  const wabtModule = require('wabt');
  wabtLoader = wabtModule as () => Promise<any>;
} catch {
  // wabt 미설치 환경: loader = null
  wabtLoader = null;
}

/** wabt 사용 가능 여부 */
export function isWabtAvailable(): boolean {
  return wabtLoader !== null;
}

// ─── 결과 타입 ────────────────────────────────────────────────────────────────

export interface WasmRunResult {
  /** 실행 성공 여부 */
  success: boolean;
  /** export 함수 호출 결과 (성공 시) */
  result?: unknown;
  /** 에러 메시지 (실패 시) */
  error?: string;
  /** 생성된 WAT 텍스트 (디버깅용) */
  wat?: string;
  /** 경고 목록 */
  warnings: string[];
}

export interface WasmModuleResult {
  /** 실행 성공 여부 */
  success: boolean;
  /** WebAssembly.Instance (성공 시) */
  instance?: WebAssembly.Instance;
  /** export 함수 이름 목록 */
  exports: string[];
  /** 생성된 WAT 텍스트 */
  wat: string;
  /** 경고 목록 */
  warnings: string[];
  /** 에러 메시지 (실패 시) */
  error?: string;
}

// ─── 메인 클래스 ──────────────────────────────────────────────────────────────

/**
 * FreeLang 소스 → WAT → WASM → 실행 파이프라인
 *
 * 사용 예:
 *   const runner = new NexusWasmRunner();
 *   const mod = await runner.compileModule(`@mode(v)\nfn add(a:i64,b:i64)->i64{return a+b}`);
 *   const result = runner.callExport(mod, 'add', [3n, 7n]);
 *   // result.result === 10n
 */
export class NexusWasmRunner {

  // ─── WAT 생성 ───────────────────────────────────────────────────────────────

  /**
   * FreeLang 소스 → WAT 문자열 생성
   */
  generateWat(source: string): { wat: string; exports: string[]; warnings: string[] } {
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const gen = new NexusWasmCodegen();
    return gen.generate(ast);
  }

  // ─── WAT → WASM 변환 ────────────────────────────────────────────────────────

  /**
   * WAT 문자열 → Uint8Array(WASM 바이너리)
   * wabt 미설치 시 에러 throw
   */
  async watToWasm(wat: string): Promise<Uint8Array> {
    if (!wabtLoader) {
      throw new Error('wabt 패키지가 설치되지 않았습니다. npm install wabt 를 실행하세요.');
    }
    const wabt = await wabtLoader();
    const module = wabt.parseWat('nexus.wat', wat);
    try {
      const binary = module.toBinary({});
      return binary.buffer;
    } finally {
      module.destroy();
    }
  }

  // ─── 모듈 컴파일 ────────────────────────────────────────────────────────────

  /**
   * FreeLang 소스 → WebAssembly.Instance (전체 파이프라인)
   */
  async compileModule(source: string): Promise<WasmModuleResult> {
    // 1. WAT 생성
    let watResult: ReturnType<NexusWasmRunner['generateWat']>;
    try {
      watResult = this.generateWat(source);
    } catch (e: any) {
      return {
        success: false,
        exports: [],
        wat: '',
        warnings: [],
        error: `WAT 생성 실패: ${e?.message ?? e}`,
      };
    }

    // 2. WASM 변환
    let wasm: Uint8Array;
    try {
      wasm = await this.watToWasm(watResult.wat);
    } catch (e: any) {
      return {
        success: false,
        exports: watResult.exports,
        wat: watResult.wat,
        warnings: watResult.warnings,
        error: `WAT→WASM 변환 실패: ${e?.message ?? e}`,
      };
    }

    // 3. WebAssembly 인스턴스화
    let instance: WebAssembly.Instance;
    try {
      const mod = await WebAssembly.instantiate(wasm);
      instance = mod.instance;
    } catch (e: any) {
      return {
        success: false,
        exports: watResult.exports,
        wat: watResult.wat,
        warnings: watResult.warnings,
        error: `WASM 인스턴스화 실패: ${e?.message ?? e}`,
      };
    }

    return {
      success: true,
      instance,
      exports: watResult.exports,
      wat: watResult.wat,
      warnings: watResult.warnings,
    };
  }

  // ─── export 함수 호출 ────────────────────────────────────────────────────────

  /**
   * 컴파일된 모듈에서 특정 export 함수 호출
   *
   * @param mod   compileModule() 결과
   * @param name  export 함수 이름
   * @param args  함수 인자 (i64는 bigint, f64/i32는 number)
   */
  callExport(mod: WasmModuleResult, name: string, args: unknown[] = []): WasmRunResult {
    if (!mod.success || !mod.instance) {
      return {
        success: false,
        error: mod.error ?? '모듈이 컴파일되지 않았습니다.',
        warnings: mod.warnings,
      };
    }

    const fn = (mod.instance.exports as any)[name];
    if (typeof fn !== 'function') {
      return {
        success: false,
        error: `export 함수 '${name}'을 찾을 수 없습니다. 사용 가능: ${Object.keys(mod.instance.exports).join(', ')}`,
        wat: mod.wat,
        warnings: mod.warnings,
      };
    }

    try {
      const result = fn(...args);
      return {
        success: true,
        result,
        wat: mod.wat,
        warnings: mod.warnings,
      };
    } catch (e: any) {
      return {
        success: false,
        error: `함수 실행 실패: ${e?.message ?? e}`,
        wat: mod.wat,
        warnings: mod.warnings,
      };
    }
  }

  // ─── 편의 메서드 ────────────────────────────────────────────────────────────

  /**
   * FreeLang 소스 컴파일 + 특정 함수 즉시 실행 (단축 메서드)
   */
  async run(source: string, fnName: string, args: unknown[] = []): Promise<WasmRunResult> {
    const mod = await this.compileModule(source);
    if (!mod.success) {
      return { success: false, error: mod.error, wat: mod.wat, warnings: mod.warnings };
    }
    return this.callExport(mod, fnName, args);
  }
}

/**
 * FreeLang Nexus - WebAssembly 실행 테스트
 *
 * Phase N.4.2 — WAT → .wasm 바이너리 변환 + Node.js 실행 검증
 *
 * 테스트 범위:
 *  1. add(a, b) → 실제 덧셈 실행
 *  2. subtract(a, b) → 실제 뺄셈 실행
 *  3. multiply(a, b) → 실제 곱셈 실행
 *  4. divide(a, b) → 실제 나눗셈 실행
 *  5. factorial(n) → 재귀 실행
 *  6. if/else 분기 실행 검증
 *  7. while 루프 실행 검증
 *  8. for-in range 루프 실행 검증
 *  9. 다중 export 함수 모두 호출
 * 10. 존재하지 않는 export 함수 → 에러 반환
 * 11. wabt 미설치 환경 skip 처리
 * 12. compileModule 성공 구조 검증
 * 13. WAT 문자열 포함 여부
 * 14. zero case (n=0)
 * 15. 음수 처리
 */

import { NexusWasmRunner, isWabtAvailable } from '../src/nexus/runtime/nexus-wasm-runner';

// ─── wabt 설치 여부 확인 ──────────────────────────────────────────────────────

const SKIP_IF_NO_WABT = !isWabtAvailable();

function conditionalTest(name: string, fn: () => Promise<void> | void): void {
  if (SKIP_IF_NO_WABT) {
    test.skip(name + ' [wabt 미설치 — skip]', fn);
  } else {
    test(name, fn);
  }
}

// ─── 헬퍼 ────────────────────────────────────────────────────────────────────

const runner = new NexusWasmRunner();

/** FreeLang 소스 → 즉시 실행 결과 (BigInt 반환) */
async function runFn(source: string, fn: string, args: bigint[]): Promise<bigint> {
  const result = await runner.run(source, fn, args);
  if (!result.success) throw new Error(result.error);
  return result.result as bigint;
}

// ─── 1. 기본 산술 함수 실행 ───────────────────────────────────────────────────

describe('WASM 실행 - 기본 산술', () => {
  conditionalTest('Test 1: add(3, 7) → 10', async () => {
    const src = `@mode(v)
fn add(a: i64, b: i64) -> i64 {
  return a + b
}`;
    const result = await runFn(src, 'add', [3n, 7n]);
    expect(result).toBe(10n);
  });

  conditionalTest('Test 2: subtract(20, 8) → 12', async () => {
    const src = `@mode(v)
fn subtract(a: i64, b: i64) -> i64 {
  return a - b
}`;
    const result = await runFn(src, 'subtract', [20n, 8n]);
    expect(result).toBe(12n);
  });

  conditionalTest('Test 3: multiply(6, 7) → 42', async () => {
    const src = `@mode(v)
fn multiply(a: i64, b: i64) -> i64 {
  return a * b
}`;
    const result = await runFn(src, 'multiply', [6n, 7n]);
    expect(result).toBe(42n);
  });

  conditionalTest('Test 4: divide(100, 4) → 25', async () => {
    const src = `@mode(v)
fn divide(a: i64, b: i64) -> i64 {
  return a / b
}`;
    const result = await runFn(src, 'divide', [100n, 4n]);
    expect(result).toBe(25n);
  });

  conditionalTest('Test 5: 음수 덧셈 add(-5, 3) → -2', async () => {
    const src = `@mode(v)
fn add(a: i64, b: i64) -> i64 {
  return a + b
}`;
    const result = await runFn(src, 'add', [-5n, 3n]);
    expect(result).toBe(-2n);
  });
});

// ─── 2. 재귀 함수 ─────────────────────────────────────────────────────────────

describe('WASM 실행 - 재귀 함수', () => {
  conditionalTest('Test 6: factorial(5) → 120', async () => {
    const src = `@mode(v)
fn factorial(n: i64) -> i64 {
  if n <= 1 {
    return 1
  }
  return n * factorial(n - 1)
}`;
    const result = await runFn(src, 'factorial', [5n]);
    expect(result).toBe(120n);
  });

  conditionalTest('Test 7: factorial(0) → 1 (base case)', async () => {
    const src = `@mode(v)
fn factorial(n: i64) -> i64 {
  if n <= 1 {
    return 1
  }
  return n * factorial(n - 1)
}`;
    const result = await runFn(src, 'factorial', [0n]);
    expect(result).toBe(1n);
  });

  conditionalTest('Test 8: factorial(1) → 1', async () => {
    const src = `@mode(v)
fn factorial(n: i64) -> i64 {
  if n <= 1 {
    return 1
  }
  return n * factorial(n - 1)
}`;
    const result = await runFn(src, 'factorial', [1n]);
    expect(result).toBe(1n);
  });
});

// ─── 3. if/else 분기 ──────────────────────────────────────────────────────────

describe('WASM 실행 - if/else 분기', () => {
  conditionalTest('Test 9: max(10, 20) → 20', async () => {
    const src = `@mode(v)
fn max_val(a: i64, b: i64) -> i64 {
  if a > b {
    return a
  } else {
    return b
  }
}`;
    const result = await runFn(src, 'max_val', [10n, 20n]);
    expect(result).toBe(20n);
  });

  conditionalTest('Test 10: max(50, 30) → 50', async () => {
    const src = `@mode(v)
fn max_val(a: i64, b: i64) -> i64 {
  if a > b {
    return a
  } else {
    return b
  }
}`;
    const result = await runFn(src, 'max_val', [50n, 30n]);
    expect(result).toBe(50n);
  });

  conditionalTest('Test 11: sign(5) → 1, sign(-3) → 0', async () => {
    const src = `@mode(v)
fn is_positive(n: i64) -> i64 {
  if n > 0 {
    return 1
  } else {
    return 0
  }
}`;
    const pos = await runFn(src, 'is_positive', [5n]);
    const neg = await runFn(src, 'is_positive', [-3n]);
    expect(pos).toBe(1n);
    expect(neg).toBe(0n);
  });
});

// ─── 4. while 루프 ────────────────────────────────────────────────────────────

describe('WASM 실행 - while 루프', () => {
  conditionalTest('Test 12: sum_to(10) while 루프 → 55', async () => {
    const src = `@mode(v)
fn sum_to(n: i64) -> i64 {
  let s = 0
  let i = 1
  while i <= n {
    s = s + i
    i = i + 1
  }
  return s
}`;
    const result = await runFn(src, 'sum_to', [10n]);
    expect(result).toBe(55n);
  });

  conditionalTest('Test 13: count_down(5) → 0', async () => {
    const src = `@mode(v)
fn count_down(n: i64) -> i64 {
  while n > 0 {
    n = n - 1
  }
  return n
}`;
    const result = await runFn(src, 'count_down', [5n]);
    expect(result).toBe(0n);
  });
});

// ─── 5. for-in range 루프 ─────────────────────────────────────────────────────

describe('WASM 실행 - for-in range 루프', () => {
  conditionalTest('Test 14: range_sum(5) → 0+1+2+3+4 = 10', async () => {
    const src = `@mode(v)
fn range_sum(n: i64) -> i64 {
  let s = 0
  for i in range(5) {
    s = s + i
  }
  return s
}`;
    const result = await runFn(src, 'range_sum', [0n]);
    expect(result).toBe(10n);
  });
});

// ─── 6. 다중 export 함수 ──────────────────────────────────────────────────────

describe('WASM 실행 - 다중 export', () => {
  conditionalTest('Test 15: 다중 함수 모두 독립 실행 가능', async () => {
    const src = `@mode(v)
fn add(a: i64, b: i64) -> i64 {
  return a + b
}
fn sub(a: i64, b: i64) -> i64 {
  return a - b
}
fn mul(a: i64, b: i64) -> i64 {
  return a * b
}`;
    const mod = await runner.compileModule(src);
    expect(mod.success).toBe(true);
    expect(mod.exports).toContain('add');
    expect(mod.exports).toContain('sub');
    expect(mod.exports).toContain('mul');

    const addR = runner.callExport(mod, 'add', [4n, 6n]);
    const subR = runner.callExport(mod, 'sub', [10n, 3n]);
    const mulR = runner.callExport(mod, 'mul', [5n, 5n]);

    expect(addR.result).toBe(10n);
    expect(subR.result).toBe(7n);
    expect(mulR.result).toBe(25n);
  });
});

// ─── 7. 에러 처리 ─────────────────────────────────────────────────────────────

describe('WASM 실행 - 에러 처리', () => {
  conditionalTest('Test 16: 존재하지 않는 export 함수 → 에러 반환', async () => {
    const src = `@mode(v)
fn add(a: i64, b: i64) -> i64 {
  return a + b
}`;
    const mod = await runner.compileModule(src);
    expect(mod.success).toBe(true);

    const result = runner.callExport(mod, 'nonexistent', []);
    expect(result.success).toBe(false);
    expect(result.error).toBeDefined();
  });

  conditionalTest('Test 17: compileModule 성공 시 instance 포함', async () => {
    const src = `@mode(v)
fn noop() -> i64 {
  return 0
}`;
    const mod = await runner.compileModule(src);
    expect(mod.success).toBe(true);
    expect(mod.instance).toBeDefined();
    expect(mod.wat).toContain('(module');
    expect(Array.isArray(mod.warnings)).toBe(true);
  });
});

// ─── 8. isWabtAvailable ───────────────────────────────────────────────────────

describe('WASM 런타임 - 환경 감지', () => {
  test('Test 18: isWabtAvailable() boolean 반환', () => {
    expect(typeof isWabtAvailable()).toBe('boolean');
  });

  test('Test 19: wabt 설치 환경에서 isWabtAvailable() === true', () => {
    // 이 테스트가 실행되려면 wabt가 설치되어 있어야 함
    // wabt가 없다면 SKIP_IF_NO_WABT = true이므로 위 테스트들이 skip됨
    if (SKIP_IF_NO_WABT) {
      expect(isWabtAvailable()).toBe(false);
    } else {
      expect(isWabtAvailable()).toBe(true);
    }
  });

  test('Test 20: generateWat — wabt 없어도 WAT 생성 가능', () => {
    const src = `@mode(v)
fn add(a: i64, b: i64) -> i64 {
  return a + b
}`;
    // generateWat은 wabt 없이도 동작 (WAT 텍스트 생성만)
    const result = runner.generateWat(src);
    expect(typeof result.wat).toBe('string');
    expect(result.wat).toContain('(module');
    expect(result.exports).toContain('add');
  });
});

