// ─── 3. if/else 분기 ──────────────────────────────────────────────────────────

describe('WASM 실행 - if/else 분기', () => {
  // if/else 실행 검증: if 분기로 변수를 설정 후 return
  conditionalTest('Test 9: if 분기 실행 — x > 0 → result = 1', async () => {
    const src = `@mode(v)
fn check_positive(x: i64) -> i64 {
  let result = 0
  if x > 0 {
    result = 1
  }
  return result
}`;
    const pos = await runFn(src, 'check_positive', [5n]);
    const neg = await runFn(src, 'check_positive', [-3n]);
    expect(pos).toBe(1n);
    expect(neg).toBe(0n);
  });

  conditionalTest('Test 10: if/else 분기 실행 — 변수 분기 설정', async () => {
    const src = `@mode(v)
fn abs_via_local(x: i64) -> i64 {
  let result = 0
  if x >= 0 {
    result = x
  } else {
    result = 0 - x
  }
  return result
}`;
    const pos = await runFn(src, 'abs_via_local', [7n]);
    const neg = await runFn(src, 'abs_via_local', [-4n]);
    expect(pos).toBe(7n);
    expect(neg).toBe(4n);
  });

  conditionalTest('Test 11: 중첩 if — if x > 10 분기', async () => {
    const src = `@mode(v)
fn classify(x: i64) -> i64 {
  let r = 0
  if x > 10 {
    r = 2
  }
  if x > 0 {
    r = r + 1
  }
  return r
}`;
    // x=15: x>10 r=2, x>0 r=3
    const big = await runFn(src, 'classify', [15n]);
    // x=5: x>10 skip, x>0 r=1
    const mid = await runFn(src, 'classify', [5n]);
    // x=-1: both skip, r=0
    const neg = await runFn(src, 'classify', [-1n]);
    expect(big).toBe(3n);
    expect(mid).toBe(1n);
    expect(neg).toBe(0n);
  });
});
